  "pokemon": "{\n  \"version\": \"1.0.0\",\n  \"context\": {\n    \"userName\": \"string\",\n    \"pokemonName\": \"string\",\n    \"pokemonHeight\": \"double\",\n    \"pokemonWeight\": \"double\",\n    \"pokemonImageUrl\": \"string\"\n  },\n  \"root\": {\n    \"type\": \"Column\",\n    \"id\": \"pokemon\",\n    \"children\": [\n      {\n        \"type\": \"Text\",\n        \"id\": \"title\",\n        \"properties\": {\n          \"text\": {\n            \"$expr\": \"concat('Trainer ', context.userName)\"\n          },\n          \"role\": \"title\"\n        }\n      },\n      {\n        \"type\": \"Text\",\n        \"id\": \"subtitle\",\n        \"properties\": {\n          \"text\": \"One host, two context sources: the app-wide shared context (the trainer) plus values this screen fetched from PokeAPI before building.\",\n          \"role\": \"subtitle\"\n        }\n      },\n      {\n        \"type\": \"Banner\",\n        \"id\": \"card\",\n        \"properties\": {\n          \"backgroundImageUrl\": {\n            \"$expr\": \"context.pokemonImageUrl\"\n          },\n          \"layout\": \"card\",\n          \"height\": 260,\n          \"contentAlignment\": \"bottomLeading\",\n          \"showScrim\": true,\n          \"cornerRadius\": 24\n        },\n        \"children\": [\n          {\n            \"type\": \"Text\",\n            \"id\": \"name\",\n            \"properties\": {\n              \"text\": {\n                \"$expr\": \"context.pokemonName\"\n              },\n              \"role\": \"title\"\n            }\n          },\n          {\n            \"type\": \"Text\",\n            \"id\": \"stats\",\n            \"properties\": {\n              \"text\": {\n                \"$expr\": \"concat('Height: ', str(context.pokemonHeight / 10.0), ' m · Weight: ', str(context.pokemonWeight / 10.0), ' kg')\"\n              },\n              \"role\": \"subtitle\"\n            }\n          }\n        ]\n      }\n    ]\n  }\n}",
