  "tip-calculator": "{\n  \"version\": \"1.0.0\",\n  \"state\": {\n    \"amount\": \"double\",\n    \"tipPercent\": \"double\"\n  },\n  \"root\": {\n    \"type\": \"Column\",\n    \"id\": \"calculator\",\n    \"children\": [\n      {\n        \"type\": \"Text\",\n        \"id\": \"title\",\n        \"properties\": {\n          \"text\": \"Tip calculator\",\n          \"role\": \"title\"\n        }\n      },\n      {\n        \"type\": \"Text\",\n        \"id\": \"subtitle\",\n        \"properties\": {\n          \"text\": \"The math lives in the document: pure Milano expressions over state.\",\n          \"role\": \"subtitle\"\n        }\n      },\n      {\n        \"type\": \"NumberField\",\n        \"id\": \"amount\",\n        \"properties\": {\n          \"label\": \"Amount\",\n          \"value\": {\n            \"$expr\": \"state.amount\"\n          }\n        },\n        \"on\": {\n          \"change\": [\n            {\n              \"action\": \"$set\",\n              \"key\": \"amount\",\n              \"value\": {\n                \"$expr\": \"event\"\n              }\n            }\n          ]\n        }\n      },\n      {\n        \"type\": \"NumberField\",\n        \"id\": \"tip\",\n        \"properties\": {\n          \"label\": \"Tip %\",\n          \"value\": {\n            \"$expr\": \"state.tipPercent\"\n          }\n        },\n        \"on\": {\n          \"change\": [\n            {\n              \"action\": \"$set\",\n              \"key\": \"tipPercent\",\n              \"value\": {\n                \"$expr\": \"event\"\n              }\n            }\n          ]\n        }\n      },\n      {\n        \"type\": \"Text\",\n        \"id\": \"tipAmount\",\n        \"properties\": {\n          \"text\": {\n            \"$expr\": \"'Tip: ' + str(double(int(state.amount * state.tipPercent / 100.0 * 100.0 + 0.5)) / 100.0)\"\n          },\n          \"visible\": {\n            \"$expr\": \"state.amount > 0.0\"\n          }\n        }\n      },\n      {\n        \"type\": \"Text\",\n        \"id\": \"total\",\n        \"properties\": {\n          \"text\": {\n            \"$expr\": \"'Total: ' + str(double(int(state.amount * (1.0 + state.tipPercent / 100.0) * 100.0 + 0.5)) / 100.0)\"\n          },\n          \"role\": \"title\",\n          \"visible\": {\n            \"$expr\": \"state.amount > 0.0\"\n          }\n        }\n      }\n    ]\n  }\n}",
